// R1F: a peer whose connection to the broker is still being opened is destroyed once it has opened or failed, not while it connects (closing a connecting WebSocket makes the browser log a warning)
function retirePeer(p) {
  if (!p) return;
  if (p.open || p.destroyed || p.disconnected) { p.destroy(); return; }
  const settle = () => { try { p.destroy(); } catch (e) {} };
  p.on('open', settle); p.on('error', settle); p.on('disconnected', settle);
}

